alter table public.members add column if not exists photo text not null default '', add column if not exists mood text not null default '', add column if not exists anniversary date;
create or replace function public.update_profile(display text,avatar text,feeling text,since text) returns void language plpgsql security definer set search_path=public as $$ begin
if length(avatar)>100000 or (avatar<>'' and avatar !~ '^data:image/jpeg;base64,[A-Za-z0-9+/=]+$') then raise exception 'Foto inválida'; end if;
update members set name=left(display,80),photo=avatar,mood=left(feeling,80),anniversary=nullif(since,'')::date where user_id=auth.uid() and approved; if not found then raise exception 'Perfil no vinculado'; end if;
end $$;
create or replace function public.my_space() returns jsonb language sql stable security definer set search_path=public as $$ select jsonb_build_object('id',m.space_id,'approved',m.approved,'name',m.name,'owner',s.owner=auth.uid(),'members',(select coalesce(jsonb_agg(jsonb_build_object('id',x.user_id,'name',x.name,'approved',x.approved,'photo',case when m.approved and x.approved then x.photo else '' end,'mood',case when m.approved and x.approved then x.mood else '' end,'anniversary',case when m.approved and x.approved then x.anniversary else null end)),'[]'::jsonb) from members x where x.space_id=m.space_id and (m.approved or x.user_id=auth.uid()))) from members m join spaces s on s.id=m.space_id where m.user_id=auth.uid() $$;
revoke execute on function public.update_profile(text,text,text,text) from public,anon;
grant execute on function public.update_profile(text,text,text,text) to authenticated;
-- Explicit columns keep inserts compatible with added profile fields.
create or replace function public.create_space(display text) returns uuid language plpgsql security definer set search_path=public as $$ declare s uuid; begin if auth.uid() is null then raise exception 'Inicia sesión'; end if; insert into spaces(owner) values(auth.uid()) returning id into s; insert into members(space_id,user_id,name,approved) values(s,auth.uid(),left(display,80),true); return s; end $$;
create or replace function public.join_space(invite_code text,display text) returns uuid language plpgsql security definer set search_path=public as $$ declare s uuid; begin if auth.uid() is null then raise exception 'Inicia sesión'; end if; select space_id into s from invites where code=upper(trim(invite_code)) and expires>now() for update; if s is null then raise exception 'Código inválido o vencido'; end if; perform 1 from spaces where id=s for update; if (select count(*) from members where space_id=s)>=2 then raise exception 'Espacio completo'; end if; insert into members(space_id,user_id,name,approved) values(s,auth.uid(),left(display,80),false); delete from invites where code=upper(trim(invite_code)); return s; end $$;